INSERT INTO member (first_name, last_name, email, web_page, short_cv, category, registration_number) VALUES 

-- ==========================================
-- 1. ΜΕΛΗ ΔΕΠ (10 συνολικά: 3 υπήρχαν + 7 νέοι)
-- ==========================================
('Γεώργιος', 'Παπαδόπουλος', 'gpapadopoulos@chaduni.gr', 'https://chaduni.gr/~gpapadopoulos', 'Καθηγητής στο τμήμα Πληροφορικής με ερευνητικά ενδιαφέροντα στην Τεχνητή Νοημοσύνη.\nΈχει δημοσιεύσει πληθώρα άρθρων σε διεθνή επιστημονικά περιοδικά και συνέδρια.\nΣυντονίζει ευρωπαϊκά ερευνητικά έργα και επιβλέπει διδακτορικές διατριβές.', 1, NULL),
('Ελένη', 'Οικονόμου', 'eoikonomou@chaduni.gr', 'https://chaduni.gr/~eoikonomou', 'Αναπληρώτρια Καθηγήτρια στον τομέα των Βάσεων Δεδομένων και Μεγάλων Δεδομένων.\nΗ έρευνά της εστιάζει στη βελτιστοποίηση ερωτημάτων και τα κατανεμημένα συστήματα.\nΔιδάσκει προπτυχιακά και μεταπτυχιακά μαθήματα διαχείρισης πληροφορίας.', 1, NULL),
('Δημήτριος', 'Κωνσταντίνου', 'dkonstantinou@chaduni.gr', 'https://chaduni.gr/~dkonstantinou', 'Επίκουρος Καθηγητής με εξειδίκευση στην Ασφάλεια Πληροφοριακών Συστημάτων.\nΑσχολείται με την κρυπτογραφία και την προστασία ιδιωτικότητας στα δίκτυα.\nΣυμμετέχει ενεργά σε επιτροπές αξιολόγησης διεθνών επιστημονικών εκδόσεων.', 1, NULL),
('Αντώνιος', 'Βλάχος', 'avlachos@chaduni.gr', 'https://chaduni.gr/~avlachos', 'Καθηγητής στον τομέα Θεωρητικής Πληροφορικής και Αλγορίθμων.\nΕιδικεύεται σε πολύπλοκα δομημένα δίκτυα και αλγοριθμική πολυπλοκότητα.\nΕίναι συγγραφέας πανεπιστημιακών συγγραμμάτων.', 1, NULL),
('Kαλλιόπη', 'Δημητριάδη', 'kdimitriadis@chaduni.gr', 'https://chaduni.gr/~kdimitriadis', 'Αναπληρώτρια Καθηγήτρια στην Τεχνολογία Λογισμικού.\nΕστιάζει στην ποιότητα κώδικα, τον ανασχεδιασμό και την αυτοματοποιημένη δοκιμή λογισμικού.\nΣυνεργάζεται με εταιρείες τεχνολογίας.', 1, NULL),
('Χρήστος', 'Αλεξίου', 'calexiou@chaduni.gr', 'https://chaduni.gr/~calexiou', 'Επίκουρος Καθηγητής στα Δίκτυα Υπολογιστών και τις Τηλεπικοινωνίες.\nΗ έρευνά του αφορά τα πρωτόκολλα 5G/6G και την ασφάλεια ασύρματων επικοινωνιών.\nΔιδάσκει προηγμένα δίκτυα.', 1, NULL),
('Σοφία', 'Μιχαηλίδου', 'smichailidou@chaduni.gr', 'https://chaduni.gr/~smichailidou', 'Καθηγήτρια με γνωστικό αντικείμενο τα Ψηφιακά Μέσα και τη Γραφιστική Υπολογιστών.\nΔιευθύνει το εργαστήριο οπτικοποίησης δεδομένων και εικονικής πραγματικότητας.', 1, NULL),
('Παύλος', 'Ανδρέου', 'pandreou@chaduni.gr', 'https://chaduni.gr/~pandreou', 'Επίκουρος Καθηγητής στα Ενσωματωμένα Συστήματα και το Διαδίκτυο των Πραγμάτων (IoT).\nΣχεδιάζει αρχιτεκτονικές υλικού χαμηλής κατανάλωσης ενέργειας.', 1, NULL),
('Μαρία-Λουίζα', 'Ζαφειρίου', 'mzafeiriou@chaduni.gr', 'https://chaduni.gr/~mzafeiriou', 'Αναπληρώτρια Καθηγήτρια στην Αλληλεπίδραση Ανθρώπου-Υπολογιστή (HCI).\nΜελετά την προσβασιμότητα ψηφιακών συστημάτων για ευπαθείς ομάδες χρηστών.', 1, NULL),
('Βασίλειος', 'Καρράς', 'vkarras@chaduni.gr', 'https://chaduni.gr/~vkarras', 'Καθηγητής με έμφαση στα Υπολογιστικά Νέφη (Cloud Computing) και τη διαχείριση πόρων.\nΈχει διατελέσει αξιολογητής σε διεθνή ερευνητικά προγράμματα.', 1, NULL),

-- ==========================================
-- 2. ΕΡΕΥΝΗΤΕΣ (8 συνολικά: 3 υπήρχαν + 5 νέοι)
-- ==========================================
('Μαρία', 'Βασιλείου', 'mvasileiou@chaduni.gr', 'https://chaduni.gr/~mvasileiou', 'Μεταδιδακτορική ερευνήτρια με εστίαση στη Μηχανική Μάθηση και την Όραση Υπολογιστών.\nΕργάζεται στην ανάπτυξη αλγορίθμων αναγνώρισης προτύπων σε ιατρικές εικόνες.\nΈχει λάβει υποτροφίες αριστείας για το ερευνητικό της έργο.', 2, NULL),
('Νικόλαος', 'Αντωνίου', 'nantoniou@chaduni.gr', 'https://chaduni.gr/~nantoniou', 'Κύριος ερευνητής στον τομέα του Υπολογιστικού Νέφους και του Διαδικτύου των Πραγμάτων.\nΣχεδιάζει αρχιτεκτονικές χαμηλής κατανάλωσης ενέργειας για έξυπνες πόλεις.\nΣυνεργάζεται με βιομηχανικούς εταίρους για την υλοποίηση πιλοτικών εφαρμογών.', 2, NULL),
('Αικατερίνη', 'Γεωργίου', 'ageorgiou@chaduni.gr', 'https://chaduni.gr/~ageorgiou', 'Ερευνήτρια στον τομέα της Επεξεργασίας Φυσικής Γλώσσας για την ελληνική γλώσσα.\nΑναπτύσσει γλωσσικά μοντέλα και εργαλεία ανάλυσης συναισθήματος.\nΈχει συμμετάσχει σε πολλά διεθνή ερευνητικά προγράμματα.', 2, NULL),
('Ιωάννης', 'Παπαδημητρίου', 'ipapadimitriou@chaduni.gr', 'https://chaduni.gr/~ipapadimitriou', 'Ερευνητής στην ασφάλεια δικτύων και την ανάλυση κακόβουλου λογισμικού.\nΣυμμετέχει σε δράσεις αντιμετώπισης κυβερνοεπιθέσεων.', 2, NULL),
('Ευγενία', 'Καλλιμάνη', 'ekallimani@chaduni.gr', 'https://chaduni.gr/~ekallimani', 'Ερευνήτρια στην Ανάκτηση Πληροφορίας και την εξόρυξη δεδομένων από τον ιστό.\nΕνδιαφέρεται για συστήματα συστάσεων.', 2, NULL),
('Θωμάς', 'Αλεξόπουλος', 'talexopoulos@chaduni.gr', 'https://chaduni.gr/~talexopoulos', 'Μεταδιδακτορικός ερευνητής στον τομέα της ρομποτικής και των αυτόνομων συστημάτων πλοήγησης.', 2, NULL),
('Δανάη', 'Στασινοπούλου', 'dstasinopoulou@chaduni.gr', 'https://chaduni.gr/~dstasinopoulou', 'Ερευνήτρια τεχνητής νοημοσύνης, εστιάζοντας σε μεθόδους εξηγήσιμης τεχνητής νοημοσύνης (XAI).', 2, NULL),
('Γεράσιμος', 'Λυμπέρης', 'glyberis@chaduni.gr', 'https://chaduni.gr/~glyberis', 'Ερευνητής κατανεμημένων συστημάτων και τεχνολογιών blockchain για ασφαλείς συναλλαγές.', 2, NULL),

